      "path": "package.json",
      "content": "{\n  \"name\": \"@wenbin_wb/dsh-bridge\",\n  \"version\": \"2.17.5\",\n  \"description\": \"DSH 远程连接/远程控制插件（remote control）：手机扫码即可在移动端/公网继续用 DeepSeek Harness，人不在电脑前也能接着干。一键局域网二维码、Cloudflare 公网隧道、自建隧道与微信 / QQ / 飞书 / Telegram Bot（多工作区/会话持久化/媒体/卡片审批/流式输出），无需自己搭公网服务器。\",\n  \"releaseNotes\": \"【v2.17.5】\\n• 修复「本轮改动」摘要从未显示（读取时机竞态）\\n• 修复按钮点击后误弹「请勿重复操作」提示\\n• 平台面板：QQ 调整为第一位，推荐标记移到 QQ\\n• 按钮交互与卡片渲染已通过真机验证\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./client/client.js\",\n    \"./locale/*\": \"./locale/*\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"client\",\n    \"locale\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\",\n    \"llms.txt\"\n  ],\n  \"scripts\": {\n    \"build:client\": \"node client/build.mjs\",\n    \"build:lark\": \"node scripts/bundle-lark.mjs\",\n    \"build:qq\": \"node scripts/bundle-qq.mjs\",\n    \"build:banner\": \"node scripts/generate-banner.mjs\",\n    \"prepack\": \"npm run build:client && npm run build:qq\",\n    \"release:github\": \"node scripts/create-github-release.mjs\",\n    \"lint\": \"eslint .\",\n    \"test\": \"node --test test/*.test.mjs\",\n    \"verify:mobile-ui\": \"node test/browser/run-all.mjs\"\n  },\n  \"dependencies\": {\n    \"qrcode\": \"^1.5.3\",\n    \"ws\": \"^8.18.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-llm\": \"0.1.0-rc.8\",\n    \"@eslint/js\": \"^10.0.1\",\n    \"@larksuite/channel\": \"^0.7.1\",\n    \"@larksuiteoapi/node-sdk\": \"^1.75.0\",\n    \"@tencent-connect/qqbot-nodejs\": \"^1.0.5\",\n    \"esbuild\": \"^0.28.2\",\n    \"eslint\": \"^10.9.1\",\n    \"espree\": \"^11.2.0\",\n    \"follow-redirects\": \"^1.16.1\",\n    \"globals\": \"^17.11.0\",\n    \"puppeteer-core\": \"^25.8.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.0-rc.6\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    }\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"license\": \"MIT\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"remote\",\n    \"remote-access\",\n    \"tunnel\",\n    \"cloudflare\",\n    \"mobile\",\n    \"smartphone\",\n    \"tablet\",\n    \"qr-code\",\n    \"qrcode\",\n    \"websocket\",\n    \"bot\",\n    \"wechat\",\n    \"qq\",\n    \"feishu\",\n    \"telegram\",\n    \"remote-control\",\n    \"remote-development\",\n    \"remote-ui\",\n    \"mobile-access\",\n    \"dsh-remote\",\n    \"dsh-bridge\",\n    \"dsh-mobile\",\n    \"dsh-remote-control\",\n    \"dsh-remote-access\",\n    \"mobile-remote\",\n    \"mobile-control\",\n    \"phone-remote\",\n    \"pwa\",\n    \"android\",\n    \"ios\",\n    \"public-tunnel\",\n    \"lan-access\",\n    \"远程连接\",\n    \"远程控制\",\n    \"远程访问\",\n    \"移动端\",\n    \"dsh移动端\",\n    \"手机远程\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/wenbin-wb/dsh-bridge.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/wenbin-wb/dsh-bridge/issues\"\n  },\n  \"homepage\": \"https://github.com/wenbin-wb/dsh-bridge\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"optionalDependencies\": {\n    \"@tencent-connect/qqbot-connector\": \"^1.2.0\"\n  }\n}\n"
